/**
 * THE MESSY SYNTHETIC SHEETS: what the rules do, and what the keys can label.
 *
 * These sheets were generated by another session to carry the things the bench
 * could not — hatching at wall-like spacing, stairs, grid lines, tables,
 * counters, dimensions — across five drafting styles. Their keys attribute
 * EVERY stroke to a feature with a type, which is what makes them usable as
 * training data rather than only as a score.
 *
 * Two jobs, both diagnostic:
 *
 *   1. turn each key into label rows, and report what the finder's candidates
 *      landed on — a key wall, a labelled non-wall, or nothing;
 *   2. score the rules on each sheet in missing / extra / net, and draw it.
 *
 * `zz` keeps it out of the gating suite. Nothing here trains anything.
 */
import { Buffer } from "node:buffer";
import { mkdirSync, readFileSync, readdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { findWallsOnSheet } from "../findWallsOnSheet";
import { sheetStrokes } from "../sheetStrokes";
import type { WallCandidate } from "../wallVectors";
import { FEATURE_NAMES } from "../wallFeatures";
import { deciderFor, type WallModel } from "../wallClassifier";

const DIR = process.env.MESSY_DIR ?? "";
const OUT = process.env.MESSY_OUT ?? "";
const LABELS = process.env.MESSY_LABELS ?? "";
const ONLY = process.env.MESSY_ONLY ?? "";
/** A trained model to decide with, instead of the rules. Off by default. */
const MODEL = process.env.MESSY_MODEL ?? "";
/** Where the model's probability becomes a yes. */
const CUT = Number(process.env.MESSY_CUT ?? "0.5");

type KeySegment = [number, number, number, number, number, number];

type MessyKey = {
  id: string;
  office: string;
  flavor: string;
  dense: boolean;
  page_size_pt: [number, number];
  views: { name: string; scale_ratio: number; pt_per_ft: number; origin_pt: [number, number] }[];
  totals: { wall_lf_gross: number; wall_lf_net: number };
  walls: {
    id: string;
    start_ft: [number, number];
    end_ft: [number, number];
    length_ft: number;
    thickness_in: number;
    exterior: boolean;
  }[];
  features: { id: number; type: string; subtype: string | null; wall_id: string | null }[];
  pieces: { segment_fields: string[]; segments: KeySegment[] };
};

type Line = { x1: number; y1: number; x2: number; y2: number };

const lengthOf = (l: Line) => Math.hypot(l.x2 - l.x1, l.y2 - l.y1);

const parallelism = (a: Line, b: Line) => {
  const la = lengthOf(a) || 1;
  const lb = lengthOf(b) || 1;
  return Math.abs(((a.x2 - a.x1) / la) * ((b.x2 - b.x1) / lb) + ((a.y2 - a.y1) / la) * ((b.y2 - b.y1) / lb));
};

const offLine = (a: Line, px: number, py: number) => {
  const len = lengthOf(a) || 1;
  return Math.abs(-(px - a.x1) * ((a.y2 - a.y1) / len) + (py - a.y1) * ((a.x2 - a.x1) / len));
};

const overlapOf = (a: Line, b: Line) => {
  const len = lengthOf(a) || 1;
  const ux = (a.x2 - a.x1) / len;
  const uy = (a.y2 - a.y1) / len;
  const at = (x: number, y: number) => (x - a.x1) * ux + (y - a.y1) * uy;
  const lo = Math.max(0, Math.min(at(b.x1, b.y1), at(b.x2, b.y2)));
  const hi = Math.min(len, Math.max(at(b.x1, b.y1), at(b.x2, b.y2)));
  return Math.max(0, hi - lo);
};

describe.skipIf(DIR === "")("the messy synthetic sheets", () => {
  it("labels the candidates and scores the rules", async () => {
    const files = readdirSync(DIR)
      .filter((f) => /^M\d+\.pdf$/.test(f))
      .filter((f) => ONLY === "" || ONLY.split(",").includes(f.replace(".pdf", "")))
      .sort();
    expect(files.length, `no M*.pdf under ${DIR}`).toBeGreaterThan(0);
    if (OUT) mkdirSync(OUT, { recursive: true });
    let decide: ((f: number[], w: WallCandidate) => number) | undefined;
    if (MODEL !== "") {
      const loaded = JSON.parse(readFileSync(MODEL, "utf8")) as WallModel;
      const scorer = deciderFor(loaded, FEATURE_NAMES);
      // Refusing beats scoring with the wrong columns, and a silent fallback
      // to the rules would be reported as the model's own result.
      expect(scorer, `the model's columns do not match this build's features`).not.toBeNull();
      // Positive is a yes and ranks; -1 is a refusal. See `decide`.
      decide = (f, w) => {
        const p = scorer!(f, w);
        return p >= CUT ? p : -1;
      };
      console.log(`deciding with ${MODEL} at ${CUT}`);
    }
    if (LABELS) mkdirSync(LABELS, { recursive: true });

    console.log(
      `\n${"sheet".padEnd(6)} ${"style".padEnd(10)} ${"key ft".padStart(8)} ${"found".padStart(8)}` +
        ` ${"missing".padStart(8)} ${"extra".padStart(8)} ${"net".padStart(8)}   candidates: wall / non-wall / nothing`,
    );

    for (const file of files) {
      const id = file.replace(".pdf", "");
      const key = JSON.parse(readFileSync(join(DIR, `${id}.json`), "utf8")) as MessyKey;
      const bytes = Buffer.from(readFileSync(join(DIR, file)));
      const read = await sheetStrokes(bytes, 1);
      if (read === null) {
        console.log(`${id}  could not be read`);
        continue;
      }

      const [widthPt, heightPt] = key.page_size_pt;
      const ptPerFt = key.views[0]?.pt_per_ft ?? 1;
      // The finder works in page-width units with y measured DOWN from the
      // top; the key is in PDF points with y UP from the bottom, which its own
      // `coordinates` field says in as many words.
      const toUnits = (xPt: number, yPt: number) => ({
        x: xPt / widthPt,
        y: (heightPt - yPt) / widthPt,
      });
      const feetPerUnit = widthPt / ptPerFt;

      // ── THE KEY'S OWN STROKES, BY FEATURE TYPE ──
      const typeOf = new Map(key.features.map((f) => [f.id, f.type]));
      const keyLines = key.pieces.segments.map((s) => {
        const a = toUnits(s[0], s[1]);
        const b = toUnits(s[2], s[3]);
        return { x1: a.x, y1: a.y, x2: b.x, y2: b.y, type: typeOf.get(s[4]) ?? "unknown" };
      });

      const keyWalls = key.walls.map((w) => {
        const origin = key.views[0]?.origin_pt ?? [0, 0];
        const a = toUnits(origin[0] + w.start_ft[0] * ptPerFt, origin[1] + w.start_ft[1] * ptPerFt);
        const b = toUnits(origin[0] + w.end_ft[0] * ptPerFt, origin[1] + w.end_ft[1] * ptPerFt);
        return { ...w, x1: a.x, y1: a.y, x2: b.x, y2: b.y };
      });

      // ── THE RUN ──
      const candidates: { features: number[]; wall: WallCandidate }[] = [];
      const found = findWallsOnSheet({
        // POINTS, not units. `findWallsOnSheet` divides by `pageSize.widthPt`
        // itself (`inPageWidthUnits`), and pre-dividing here made every
        // coordinate 2,592 times too small — which produced zero candidates on
        // every sheet, including the two-line ones the engine is built for.
        // Checked against a `pairs` sheet before believing any zero.
        segments: read.segments,
        textItems: [],
        pageSize: { widthPt, heightPt },
        feetPerUnit,
        wallTypes: [],
        sampledSheets: null,
        onCandidate: (features: number[], wall: WallCandidate) =>
          candidates.push({ features, wall }),
        decide,
      });

      // CONTROLS: a zero further down is only readable if these are not zero.
      console.log(
        `${id}: ${read.segments.length} strokes read, ${keyLines.length} key strokes, ` +
          `${keyWalls.length} key walls, ${candidates.length} candidates, ${found.walls.length} runs ` +
          `| ${feetPerUnit.toFixed(1)} ft per unit, page ${widthPt}x${heightPt}`,
      );
      console.log(
        `  dropped: layer ${found.layerDropped}, grid ${found.gridDropped}, ` +
          `template ${found.templateDropped}, hatch ${found.hatchDropped}, ` +
          `duplicate ${found.duplicateDropped} | everywhere ${found.everywhere.length}, ` +
          `inBuilding ${found.inBuilding.length}`,
      );
      console.log(
        `  stroke extent: x ${Math.min(...read.segments.map((s) => s.x1)).toFixed(0)}-${Math.max(...read.segments.map((s) => s.x2)).toFixed(0)} pt` +
          `, key wall 1 at (${(keyWalls[0]?.x1 ?? 0).toFixed(3)},${(keyWalls[0]?.y1 ?? 0).toFixed(3)}) units`,
      );

      // ── WHAT EACH CANDIDATE LANDED ON ──
      //
      // The key attributes every stroke to a feature, so a candidate's own
      // line is matched against those strokes rather than guessed at. A
      // candidate that sits on nothing is the interesting case and is counted
      // separately rather than folded into "not a wall".
      let onWall = 0;
      let onOther = 0;
      let onNothing = 0;
      const otherTypes = new Map<string, number>();
      const nothings: WallCandidate[] = [];
      const rows: { features: number[]; label: 0 | 1; lengthFt: number; on: string }[] = [];

      for (const { features, wall } of candidates) {
        const band = Math.max(wall.thicknessFeet / feetPerUnit, 0.002);
        let hit: string | null = null;
        // A key WALL first: the candidate is meant to be one of its faces.
        for (const kw of keyWalls) {
          if (parallelism(kw, wall) < 0.98) continue;
          if (offLine(kw, (wall.x1 + wall.x2) / 2, (wall.y1 + wall.y2) / 2) > band * 1.5) continue;
          if (overlapOf(kw, wall) < 0.5 * Math.min(lengthOf(kw), lengthOf(wall))) continue;
          hit = "wall";
          break;
        }
        if (hit === null) {
          for (const kl of keyLines) {
            if (kl.type === "wall") continue;
            if (parallelism(kl, wall) < 0.98) continue;
            if (offLine(kl, (wall.x1 + wall.x2) / 2, (wall.y1 + wall.y2) / 2) > band * 1.5) continue;
            if (overlapOf(kl, wall) < 0.4 * Math.min(lengthOf(kl), lengthOf(wall))) continue;
            hit = kl.type;
            break;
          }
        }
        if (hit === "wall") onWall += 1;
        else if (hit !== null) {
          onOther += 1;
          otherTypes.set(hit, (otherTypes.get(hit) ?? 0) + 1);
        } else {
          onNothing += 1;
          if (nothings.length < 6) nothings.push(wall);
        }
        rows.push({
          features,
          label: hit === "wall" ? 1 : 0,
          lengthFt: wall.lengthFeet,
          on: hit ?? "nothing",
        });
      }

      // ── MISSING / EXTRA / NET, in feet ──
      const runs = found.walls;
      let missing = 0;
      for (const kw of keyWalls) {
        const covered = runs.some(
          (r) =>
            parallelism(kw, r) > 0.98 &&
            offLine(kw, (r.x1 + r.x2) / 2, (r.y1 + r.y2) / 2) <=
              Math.max(r.thicknessFeet / feetPerUnit, 0.002) * 2 &&
            overlapOf(kw, r) >= 0.5 * Math.min(lengthOf(kw), lengthOf(r)),
        );
        if (!covered) missing += w_lengthOf(kw);
      }
      let extra = 0;
      for (const r of runs) {
        const onAWall = keyWalls.some(
          (kw) =>
            parallelism(kw, r) > 0.98 &&
            offLine(kw, (r.x1 + r.x2) / 2, (r.y1 + r.y2) / 2) <=
              Math.max(r.thicknessFeet / feetPerUnit, 0.002) * 2 &&
            overlapOf(kw, r) >= 0.5 * Math.min(lengthOf(kw), lengthOf(r)),
        );
        if (!onAWall) extra += r.lengthFeet;
      }
      const foundFt = runs.reduce((n, r) => n + r.lengthFeet, 0);

      console.log(
        `${id.padEnd(6)} ${key.office.padEnd(10)} ${key.totals.wall_lf_gross.toFixed(0).padStart(8)}` +
          ` ${foundFt.toFixed(0).padStart(8)} ${missing.toFixed(0).padStart(8)} ${extra.toFixed(0).padStart(8)}` +
          ` ${(extra - missing).toFixed(0).padStart(8)}   ${onWall} / ${onOther} / ${onNothing}` +
          (otherTypes.size > 0
            ? `  [${[...otherTypes.entries()].sort((a, b) => b[1] - a[1]).slice(0, 4).map(([t, n]) => `${t} ${n}`).join(", ")}]`
            : ""),
      );
      if (nothings.length > 0) {
        console.log(
          `       on nothing, longest: ` +
            nothings
              .sort((a, b) => b.lengthFeet - a.lengthFeet)
              .slice(0, 3)
              .map(
                (w) =>
                  `${w.lengthFeet.toFixed(1)}ft@${(w.thicknessFeet * 12).toFixed(1)}in ` +
                  `(${(w.x1 * feetPerUnit).toFixed(0)},${(w.y1 * feetPerUnit).toFixed(0)})`,
              )
              .join("  "),
        );
      }

      if (LABELS) {
        writeFileSync(
          join(LABELS, `${id}.json`),
          JSON.stringify(
            {
              format: "takeoff-labels-v1",
              set: "synthetic-messy",
              sheet: id,
              office: key.office,
              flavor: key.flavor,
              dense: key.dense,
              feetPerUnit,
              featureNames: [...FEATURE_NAMES],
              reviewComplete: true,
              counts: { onWall, onOther, onNothing },
              rows,
            },
            null,
            1,
          ),
          "utf8",
        );
      }

      if (OUT) {
        const scale = 1 / widthPt;
        void scale;
        const grey = read.segments
          .map(
            (s) =>
              `<line x1="${s.x1.toFixed(1)}" y1="${s.y1.toFixed(1)}" x2="${s.x2.toFixed(1)}" y2="${s.y2.toFixed(1)}"/>`,
          )
          .join("");
        const red = runs
          .map(
            (r) =>
              `<line x1="${(r.x1 * widthPt).toFixed(1)}" y1="${(r.y1 * widthPt).toFixed(1)}" x2="${(r.x2 * widthPt).toFixed(1)}" y2="${(r.y2 * widthPt).toFixed(1)}"/>`,
          )
          .join("");
        const green = keyWalls
          .map(
            (w) =>
              `<line x1="${(w.x1 * widthPt).toFixed(1)}" y1="${(w.y1 * widthPt).toFixed(1)}" x2="${(w.x2 * widthPt).toFixed(1)}" y2="${(w.y2 * widthPt).toFixed(1)}"/>`,
          )
          .join("");
        writeFileSync(
          join(OUT, `${id}.svg`),
          `<svg xmlns="http://www.w3.org/2000/svg" width="${widthPt}" height="${heightPt}" viewBox="0 0 ${widthPt} ${heightPt}">\n` +
            `<rect width="100%" height="100%" fill="#fff"/>\n` +
            `<g stroke="#c9ced6" stroke-width="0.6" fill="none">${grey}</g>\n` +
            `<g stroke="#16a34a" stroke-width="5" fill="none" stroke-opacity="0.45">${green}</g>\n` +
            `<g stroke="#e11d48" stroke-width="2.2" fill="none">${red}</g>\n</svg>\n`,
          "utf8",
        );
      }
    }
    expect(files.length).toBeGreaterThan(0);
  }, 3000000);
});

/** The key's own length for a wall, in feet, from its declared endpoints. */
function w_lengthOf(w: { length_ft: number }): number {
  return w.length_ft;
}
